import type { Route } from "next";
// Generated by Next (`next typegen` / `next build`) from the app directory.
import type { AppRoutes } from "../../../.next/types/routes";

/*
 * Brand sites live at /b/[brand]/… internally but are served on their own domain with clean URLs
 * (proxy.ts rewrites lumiere.in/services → /b/lumiere/services). typedRoutes only knows the internal paths,
 * so brand links use brandHref("/services"): it is type-checked against the real brand routes
 * (a typo or a removed page fails the build) and returns the clean URL.
 */
type Strip<R> = R extends `/b/[brand]${infer P}` ? (P extends "" ? "/" : P) : never;
type FillParams<S extends string> = S extends `${infer A}[${string}]${infer B}` ? `${A}${string}${FillParams<B>}` : S;
type BrandRoute = FillParams<Strip<AppRoutes>>;
export type BrandPath = BrandRoute | `${BrandRoute}#${string}` | `${BrandRoute}?${string}`;

export const brandHref = (path: BrandPath) => path as unknown as Route;
